        String body = Formatter.formatMoney(reservation.refund());

        messageService.send(
            MessageChannel.EMAIL,
            "financeiro@pousadamarealta.com.br",
            String.format("Reembolso - reserva %d", reservation.id()),
            body
        );
    }
}

